(function(){"use strict";function initRegisterInfoModal(){const modal=document.getElementById("gstore-register-info-modal");const openBtn=document.querySelector(".gstore-register-info-btn");const closeBtn=document.querySelector(".gstore-modal__close");const overlay=document.querySelector(".gstore-modal__overlay");if(!modal||!openBtn){return}function openModal(){modal.setAttribute("aria-hidden","false");document.body.style.overflow="hidden";const firstFocusable=modal.querySelector('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])');if(firstFocusable){firstFocusable.focus()}}function closeModal(){modal.setAttribute("aria-hidden","true");document.body.style.overflow="";if(openBtn){openBtn.focus()}}openBtn.addEventListener("click",function(e){e.preventDefault();openModal()});if(closeBtn){closeBtn.addEventListener("click",closeModal)}if(overlay){overlay.addEventListener("click",closeModal)}document.addEventListener("keydown",function(e){if(e.key==="Escape"&&modal.getAttribute("aria-hidden")==="false"){closeModal()}});const modalContent=document.querySelector(".gstore-modal__content");if(modalContent){modalContent.addEventListener("click",function(e){e.stopPropagation()})}}function initDashboardAnimations(){const dashboard=document.querySelector(".gstore-dashboard");if(!dashboard)return;const elements=dashboard.querySelectorAll(".gstore-dashboard__welcome, "+".gstore-dashboard__stat-card, "+".gstore-dashboard__action-card, "+".gstore-dashboard__order-card");if(!elements.length)return;const observerOptions={root:null,rootMargin:"0px",threshold:.1};const observer=new IntersectionObserver(entries=>{entries.forEach((entry,index)=>{if(entry.isIntersecting){setTimeout(()=>{entry.target.classList.add("is-visible")},index*50);observer.unobserve(entry.target)}})},observerOptions);elements.forEach(el=>{el.style.opacity="0";el.style.transform="translateY(20px)";el.style.transition="opacity 0.4s ease, transform 0.4s ease";observer.observe(el)});const style=document.createElement("style");style.textContent=`\n\t\t\t.gstore-dashboard .is-visible {\n\t\t\t\topacity: 1 !important;\n\t\t\t\ttransform: translateY(0) !important;\n\t\t\t}\n\t\t`;document.head.appendChild(style)}function initMobileNavigation(){const nav=document.querySelector(".gstore-myaccount-nav");if(!nav)return;const navList=nav.querySelector(".gstore-myaccount-nav__list");const activeItem=nav.querySelector(".gstore-myaccount-nav__item.is-active");if(window.innerWidth<=768&&activeItem&&navList){setTimeout(()=>{const navRect=navList.getBoundingClientRect();const itemRect=activeItem.getBoundingClientRect();if(itemRect.left<navRect.left||itemRect.right>navRect.right){activeItem.scrollIntoView({behavior:"smooth",block:"nearest",inline:"center"})}},100)}}function initActionFeedback(){const actionCards=document.querySelectorAll(".gstore-dashboard__action-card");actionCards.forEach(card=>{card.addEventListener("click",function(e){const ripple=document.createElement("span");const rect=card.getBoundingClientRect();ripple.style.cssText=`\n\t\t\t\t\tposition: absolute;\n\t\t\t\t\twidth: 100px;\n\t\t\t\t\theight: 100px;\n\t\t\t\t\tbackground: rgba(255, 255, 255, 0.3);\n\t\t\t\t\tborder-radius: 50%;\n\t\t\t\t\ttransform: translate(-50%, -50%) scale(0);\n\t\t\t\t\tanimation: ripple 0.6s ease-out;\n\t\t\t\t\tpointer-events: none;\n\t\t\t\t\tleft: ${e.clientX-rect.left}px;\n\t\t\t\t\ttop: ${e.clientY-rect.top}px;\n\t\t\t\t`;card.style.position="relative";card.style.overflow="hidden";card.appendChild(ripple);setTimeout(()=>ripple.remove(),600)})});if(!document.querySelector("#gstore-ripple-style")){const style=document.createElement("style");style.id="gstore-ripple-style";style.textContent=`\n\t\t\t\t@keyframes ripple {\n\t\t\t\t\tto {\n\t\t\t\t\t\ttransform: translate(-50%, -50%) scale(4);\n\t\t\t\t\t\topacity: 0;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t`;document.head.appendChild(style)}}function initCPFMask(){const cpfInputs=document.querySelectorAll('input[name="billing_cpf"], input[id*="cpf"], input[id*="CPF"]');cpfInputs.forEach(input=>{input.addEventListener("input",function(e){let value=e.target.value.replace(/\D/g,"");if(value.length>11){value=value.slice(0,11)}if(value.length>9){value=value.replace(/(\d{3})(\d{3})(\d{3})(\d{1,2})/,"$1.$2.$3-$4")}else if(value.length>6){value=value.replace(/(\d{3})(\d{3})(\d{1,3})/,"$1.$2.$3")}else if(value.length>3){value=value.replace(/(\d{3})(\d{1,3})/,"$1.$2")}e.target.value=value});input.addEventListener("keypress",function(e){if(!/[0-9]/.test(e.key)&&e.key!=="Backspace"&&e.key!=="Delete"&&e.key!=="Tab"){e.preventDefault()}})})}function initFormValidation(){const forms=document.querySelectorAll(".woocommerce-form, .woocommerce-EditAccountForm");forms.forEach(form=>{const inputs=form.querySelectorAll("input[required], select[required], textarea[required]");inputs.forEach(input=>{input.addEventListener("blur",function(){validateField(this)});input.addEventListener("input",function(){const wrapper=this.closest(".form-row");if(wrapper&&wrapper.classList.contains("woocommerce-invalid")){wrapper.classList.remove("woocommerce-invalid");wrapper.classList.add("woocommerce-validated")}})})});function validateField(field){const wrapper=field.closest(".form-row");if(!wrapper)return;const isValid=field.checkValidity();wrapper.classList.remove("woocommerce-invalid","woocommerce-validated");wrapper.classList.add(isValid?"woocommerce-validated":"woocommerce-invalid")}}function initCharacterCounters(){const textareas=document.querySelectorAll("textarea[maxlength]");textareas.forEach(textarea=>{const maxLength=textarea.getAttribute("maxlength");if(!maxLength)return;const counter=document.createElement("span");counter.className="gstore-char-counter";counter.style.cssText=`\n\t\t\t\tdisplay: block;\n\t\t\t\ttext-align: right;\n\t\t\t\tfont-size: 12px;\n\t\t\t\tcolor: var(--gstore-color-text-secondary, #6b6b6b);\n\t\t\t\tmargin-top: 4px;\n\t\t\t`;updateCounter();textarea.parentNode.appendChild(counter);textarea.addEventListener("input",updateCounter);function updateCounter(){const remaining=maxLength-textarea.value.length;counter.textContent=`${textarea.value.length}/${maxLength}`;counter.style.color=remaining<20?"var(--gstore-color-warning, #b5a642)":"var(--gstore-color-text-secondary, #6b6b6b)"}})}function initFormLoadingStates(){const forms=document.querySelectorAll(".woocommerce-form, .woocommerce-EditAccountForm");forms.forEach(form=>{form.addEventListener("submit",function(e){const submitBtn=form.querySelector('button[type="submit"], input[type="submit"]');if(!submitBtn)return;if(!form.checkValidity())return;setTimeout(()=>{submitBtn.classList.add("is-loading");if(submitBtn.tagName==="BUTTON"){submitBtn.innerHTML='<span class="gstore-spinner"></span> Processando...'}else{submitBtn.value="Processando..."}},10);if(!document.querySelector("#gstore-spinner-style")){const style=document.createElement("style");style.id="gstore-spinner-style";style.textContent=`\n\t\t\t\t\t\t.gstore-spinner {\n\t\t\t\t\t\t\tdisplay: inline-block;\n\t\t\t\t\t\t\twidth: 14px;\n\t\t\t\t\t\t\theight: 14px;\n\t\t\t\t\t\t\tborder: 2px solid rgba(255, 255, 255, 0.3);\n\t\t\t\t\t\t\tborder-top-color: #fff;\n\t\t\t\t\t\t\tborder-radius: 50%;\n\t\t\t\t\t\t\tanimation: gstore-spin 0.8s linear infinite;\n\t\t\t\t\t\t\tvertical-align: middle;\n\t\t\t\t\t\t\tmargin-right: 8px;\n\t\t\t\t\t\t}\n\t\t\t\t\t\t@keyframes gstore-spin {\n\t\t\t\t\t\t\tto { transform: rotate(360deg); }\n\t\t\t\t\t\t}\n\t\t\t\t\t\t.is-loading {\n\t\t\t\t\t\t\topacity: 0.8;\n\t\t\t\t\t\t\tcursor: wait;\n\t\t\t\t\t\t}\n\t\t\t\t\t`;document.head.appendChild(style)}})})}function initRegisterButton(){const registerBtn=document.querySelector(".gstore-btn-register");const registerColumn=document.querySelector(".u-column2.col-2");const columnsWrapper=document.querySelector(".u-columns.col2-set");if(!registerBtn||!registerColumn)return;registerBtn.addEventListener("click",function(e){e.preventDefault();const isVisible=registerColumn.classList.contains("is-visible");if(isVisible){registerColumn.classList.remove("is-visible");columnsWrapper?.classList.remove("show-register");registerBtn.textContent="Cadastrar-se"}else{registerColumn.classList.add("is-visible");columnsWrapper?.classList.add("show-register");registerBtn.textContent="Voltar ao login";setTimeout(()=>{registerColumn.scrollIntoView({behavior:"smooth",block:"start"});const firstInput=registerColumn.querySelector('input:not([type="hidden"])');if(firstInput){firstInput.focus()}},100)}})}function initExistingAccountRecoveryFallback(){const storageKey="gstore_existing_account_email";function isLostPasswordPage(){return window.location.pathname.indexOf("lost-password")!==-1}function getLostPasswordUrl(){const lostPasswordAnchor=document.querySelector(".woocommerce-LostPassword a[href]");if(lostPasswordAnchor&&lostPasswordAnchor.href){return lostPasswordAnchor.href}if(window.gstoreAccountUrls&&window.gstoreAccountUrls.myAccount){const base=String(window.gstoreAccountUrls.myAccount).replace(/\/+$/,"/");return`${base}lost-password/`}return"/minha-conta/lost-password/"}function readStoredEmail(){try{return sessionStorage.getItem(storageKey)||""}catch(e){return""}}function writeStoredEmail(email){if(!email)return;try{sessionStorage.setItem(storageKey,email)}catch(e){}}function clearStoredEmail(){try{sessionStorage.removeItem(storageKey)}catch(e){}}const registerForm=document.querySelector("form.woocommerce-form-register");const registerEmailInput=document.querySelector("#reg_email");if(registerForm&&registerEmailInput){registerForm.addEventListener("submit",function(){const email=(registerEmailInput.value||"").trim();if(email){writeStoredEmail(email)}})}if(!isLostPasswordPage()){const duplicateNoticeEl=document.querySelector(".woocommerce-error, .wc-block-components-notice-banner.is-error");const duplicateText=duplicateNoticeEl?(duplicateNoticeEl.textContent||"").toLowerCase():"";const isDuplicateEmailError=duplicateText.indexOf("já existe uma conta cadastrada")!==-1||duplicateText.indexOf("already registered")!==-1||duplicateText.indexOf("account is already registered")!==-1;if(isDuplicateEmailError){const matchedEmail=duplicateText.match(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i);if(matchedEmail&&matchedEmail[0]){writeStoredEmail(matchedEmail[0])}else if(registerEmailInput&&registerEmailInput.value){writeStoredEmail(registerEmailInput.value.trim())}const target=new URL(getLostPasswordUrl(),window.location.origin);target.searchParams.set("gstore_existing_account","1");window.location.replace(target.toString())}}if(isLostPasswordPage()){const params=new URLSearchParams(window.location.search);const hasExistingAccountFlag=params.get("gstore_existing_account")==="1";if(hasExistingAccountFlag){const lostForm=document.querySelector("form.woocommerce-ResetPassword");const hasBanner=!!document.querySelector(".gstore-lost-password__notice");if(lostForm&&!hasBanner){const notice=document.createElement("div");notice.className="gstore-lost-password__notice";notice.setAttribute("role","status");notice.setAttribute("aria-live","polite");notice.innerHTML='<p>Este e-mail já está cadastrado. Para acessar sua conta, recupere sua senha abaixo. Depois de clicar em "Redefinir senha", você receberá um e-mail com o link para criar uma nova senha.</p>';lostForm.insertBefore(notice,lostForm.firstChild)}}const loginInput=document.querySelector("#user_login");const storedEmail=readStoredEmail();if(loginInput&&!loginInput.value&&storedEmail){loginInput.value=storedEmail;clearStoredEmail()}}}function init(){initRegisterInfoModal();initDashboardAnimations();initMobileNavigation();initActionFeedback();initCPFMask();initFormValidation();initCharacterCounters();initFormLoadingStates();initRegisterButton();initExistingAccountRecoveryFallback()}if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",init)}else{init()}})();
